                post_hook={
                    "sql": "create or replace table beastlife-wh-474411.maplemonk.D2C_master_pre as select sc.source medium, sc.channel source, sc.utm_campaign, sc.utm_term, order_status, sc.Order_Date, sc.ordeR_time, sc.marketplace, sc.customer_id, sc.app_website_flag, sc.new_customer_flag, sc.user_id, sc.NAME, sc.EMAIL, sc.PHONE, sc.pincode, sc.ORDER_ID, sc.reference_Code ordeR_name, sc.SKU, sc.PRODUCT_NAME, sc.PRODUCT_CATEGORY, sc.PRODUCT_SUB_CATEGORY, sc.discount_codes, sc.selling_price, sc.quantity, sc.TAX, sc.SHIPPING_PRICE, sc.DISCOUNT, cm.customer_segment, sc.cod_flag, sc.cod_pp_flag, case when (lower(ARRAY_TO_STRING(properties, \',\')) like \'%bie%\' or lower(ARRAY_TO_STRING(properties, \',\')) like \'%payday%\' or lower(ARRAY_TO_STRING(properties, \',\')) like \'%free shaker%\' or lower(ARRAY_TO_STRING(properties, \',\')) like \'%free tshirt%\' or lower(ARRAY_TO_STRING(properties, \',\')) like \'%free gift%\' or lower(ARRAY_TO_STRING(properties, \',\')) like \'%mrt%\' or (lower(ARRAY_TO_STRING(properties, \',\')) like \'%pr%\' and lower(ARRAY_TO_STRING(properties, \',\')) not like \'%price%\') or (lower(ARRAY_TO_STRING(properties, \',\')) like \'%gift%\' and lower(ARRAY_TO_STRING(properties, \',\')) not like \'%gift_card%\')) or ((discount_codes like \'%7AJGZ3HJ9DYV%\' or discount_codes like \'%T4RBQB%\') and sc.sku = \'BL003\') then 1 when b.sku is not null then 1 else 0 end freebie_flag, coalesce(mcf.account_name, mcg.account_name) account_name, mcf.ad_name ad_name, mcf.adset_name adset_name, coalesce(mcf.campaign_name, mcg.campaign_name) campaign_name, ( SELECT JSON_VALUE(t, \'$.value\') FROM UNNEST(JSON_EXTRACT_ARRAY(note_attributes)) AS t WHERE JSON_VALUE(t, \'$.name\') = \'source\' ) AS source_app_web, ( SELECT JSON_VALUE(t, \'$.value\') FROM UNNEST(JSON_EXTRACT_ARRAY(note_attributes)) AS t WHERE JSON_VALUE(t, \'$.name\') = \'platform\' ) AS platform, c.status shipment_Status from beastlife-wh-474411.maplemonk.beastlife_wh_474411_sales_consolidated as sc left join (select * from beastlife-wh-474411.maplemonk.beastlife_wh_474411_CUSTOMER_MASTER where acquisition_marketplace = \'WEBSITE\') as cm on cm.mm_customer_id = sc.customer_id_final left join ( select * from ( select distinct ad_name, ad_id, adset_name, account_name, campaign_name, row_number() over (partition by ad_id order by 1) rw from beastlife-wh-474411.maplemonk.beastlife_wh_474411_MARKETING_CONSOLIDATED where channel = \'FACEBOOK\')where rw = 1 and ad_id is not null) mcf on sc.utm_term = mcf.ad_id left join ( select * from ( select distinct campaign_name, campaign_id, account_name, row_number() over (partition by campaign_id order by 1) rw from beastlife-wh-474411.maplemonk.beastlife_wh_474411_MARKETING_CONSOLIDATED where channel = \'GOOGLE\')where rw = 1 and campaign_id is not null) mcg on sc.utm_term = mcg.campaign_id left join beastlife-wh-474411.maplemonk.google_sheet_sku_coupon b on LOWER((sc.note_attributes)) like lower(CONCAT(\'%\', b.coupon, \'%\')) and lower(sc.sku) = lower(b.sku) left join ( select distinct channel_ordeR_id, channel_sku, status from maplemonk.beastlife_shiprocket_fact_items where channel_ordeR_id <>\'R\' ) c on sc.reference_code = c.channel_ordeR_id and sc.sku = c.channel_sku ; create or replace table beastlife-wh-474411.maplemonk.D2C_master as select medium, source, utm_campaign, utm_term, order_status, Order_Date, ordeR_time, marketplace, customer_id, app_website_flag, new_customer_flag, user_id, NAME, EMAIL, PHONE, pincode, ORDER_ID, a.ordeR_name, SKU, PRODUCT_NAME, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, discount_codes, case when a.freebie_flag = 1 then 0 else a.selling_price + ifnull(b.selling_price_freebie,0)*safe_divide(selling_price,c.selling_price_without_freebie) end as selling_price, case when freebie_flag = 1 then 0 else quantity end as quantity, case when freebie_flag = 1 then quantity end as freebie_quantity, TAX, SHIPPING_PRICE, DISCOUNT, customer_segment, freebie_flag, cod_flag, cod_pp_flag, account_name, ad_name, adset_name, campaign_name, source_app_web, platform, shipment_Status from beastlife-wh-474411.maplemonk.D2C_master_pre a left join (select ordeR_name, sum(selling_price) selling_price_freebie from beastlife-wh-474411.maplemonk.D2C_master_pre where freebie_flag = 1 group by 1) b on a.ordeR_name = b.ordER_name left join (select ordeR_name, sum(selling_price) selling_price_without_freebie from beastlife-wh-474411.maplemonk.D2C_master_pre where freebie_flag = 0 group by 1) c on a.ordeR_name = c.ordER_name ;",
